import{_ as o,o as t,c as s,a2 as i}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"ADR-079 — Asset-origin spine + source/derived separation + WebP delivery (closes #373 root cause; delivers mobile streaming)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-079.md","filePath":"adr/ADR-079.md"}'),r={name:"adr/ADR-079.md"};function a(n,e,d,c,l,u){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-079-—-asset-origin-spine-source-derived-separation-webp-delivery-closes-373-root-cause-delivers-mobile-streaming" tabindex="-1">ADR-079 — Asset-origin spine + source/derived separation + WebP delivery (closes #373 root cause; delivers mobile streaming) <a class="header-anchor" href="#adr-079-—-asset-origin-spine-source-derived-separation-webp-delivery-closes-373-root-cause-delivers-mobile-streaming" aria-label="Permalink to &quot;ADR-079 — Asset-origin spine + source/derived separation + WebP delivery (closes #373 root cause; delivers mobile streaming)&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-07-07 Gates · #373 (GH Pages deploy flakiness) · mobile epic #149 S3 (#191) · v0.7.3 / v0.8</p></blockquote><p><strong>Gating sentence</strong>: heavy-media asset URLs resolve through a single <code>assetUrl(path, kind)</code> spine whose origin is configurable (local by default; <code>chipi.github.io</code> under the Capacitor <code>__MOBILE__</code> build; an optional prod CDN later), build-time <strong>source</strong> (the 10,360-file i18n overlay tree, image <strong>masters</strong>) lives outside the served <code>static/</code> tree so only <strong>derived</strong> outputs ship, and delivery images are <strong>WebP</strong> re-encoded locally from masters and committed — CI validates and deploys but never encodes.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Two problems share one root cause.</p><ol><li><p><strong>#373 — GH Pages deploys are a coin-flip.</strong> The built site is <strong>2.1 GB across 30,812 files</strong>, over GitHub Pages&#39; 1 GB <em>and</em> file-count soft limits; the publish step times out ~40% of the time. Measured 2026-07-07 on <code>main</code>: <strong>10,360 of 17,161 <code>static/</code> files (60%) are the raw per-entity i18n overlay tree</strong> (<code>static/data/i18n/&lt;locale&gt;/…</code>) — which is <strong>never fetched at runtime</strong> (the app loads the 14 collapsed <code>{locale}.json</code> bundles via <code>loadI18nBundle</code>; the raw tree is build-time source that <code>build-i18n-bundles.mjs</code> consumes). It only inflates the deploy because it is misfiled inside <code>static/</code>, which <code>adapter-static</code> copies wholesale. Separately, <code>static/images</code> is 1.6 GB of <strong>JPEG</strong> (5,308 files, 0 WebP) — the byte bulk.</p></li><li><p><strong>Mobile stream-heavy (ADR-078)</strong> needs the same heavy buckets (images, audio, non-default-locale data) served from <code>chipi.github.io</code> under the Capacitor build. A resolver audit found these URLs are built at <strong>~9 scattered chokepoints</strong> with no central helper, and with a real inconsistency in audio (<code>audio-registry</code> stores <code>${base}${path_mp3}</code> while <code>colophon</code> stores the raw path and prepends <code>${base}</code> at render — a latent double-prepend bug).</p></li></ol><p>Both trace to: <strong>too much media + too many files in one served build</strong>, <strong>scattered/inconsistent asset-URL construction</strong>, and <strong>build-time source misfiled as servable assets</strong>. Marko also flagged a future need for an <em>optional</em> CDN when Orrery moves to VPS prod — so the origin must be a configurable seam, not a mobile-only hack.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="d1-—-asseturl-origin-spine" tabindex="-1">D1 — <code>assetUrl()</code> origin spine <a class="header-anchor" href="#d1-—-asseturl-origin-spine" aria-label="Permalink to &quot;D1 — `assetUrl()` origin spine&quot;">​</a></h3><p>Introduce one helper (<code>src/lib/asset-url.ts</code>) — <code>assetUrl(path, kind)</code> — through which every heavy-bucket URL (images, audio, per-locale i18n JSON) resolves. Its origin is configurable:</p><ul><li><strong>default:</strong> the SvelteKit <code>base</code> (browser dev / GH Pages / VPS prod) — behaviour unchanged.</li><li><strong><code>__MOBILE__</code> build:</strong> <code>https://chipi.github.io/orrery</code> for pruned buckets (this is exactly the mobile S3 / #191 streaming switch — <strong>this ADR delivers #191</strong>).</li><li><strong>future:</strong> an optional prod CDN origin via env, the same seam.</li></ul><p>The ~9 chokepoints (<code>pickHero</code>; the 4 <code>data.ts</code> gallery builders; <code>spacecraft-diagrams</code>; <code>pickVariant</code> — which the 239 MB hotspots inherit; <code>audio-registry</code>; <code>loadI18nBundle</code>) route through it. The audio-<code>base</code> inconsistency is canonicalized here (one place applies base/origin; <code>colophon</code> aligns).</p><h3 id="d2-—-source-derived-separation" tabindex="-1">D2 — Source / derived separation <a class="header-anchor" href="#d2-—-source-derived-separation" aria-label="Permalink to &quot;D2 — Source / derived separation&quot;">​</a></h3><p>Build-time <strong>source</strong> must not live in the served tree.</p><ul><li><strong>i18n:</strong> move the raw overlay tree <code>static/data/i18n/&lt;locale&gt;/</code> → a non-served <code>i18n-src/</code>; <code>build-i18n-bundles.mjs</code> reads from there and writes the 14 collapsed <code>{locale}.json</code> bundles into <code>static/data/i18n/</code>. Cuts ~60% of <code>static/</code> file count from every build — the direct #373 file-count fix.</li><li><strong>images:</strong> introduce a non-served <strong><code>masters/</code></strong> store for originals; the build/pipeline re-encodes to derivatives that ship in <code>static/images/</code>.</li></ul><p>Principle: same as <code>.ts</code> → <code>.js</code> — keep source, ship the compiled derivative.</p><h3 id="d3-—-webp-only-delivery" tabindex="-1">D3 — WebP-only delivery <a class="header-anchor" href="#d3-—-webp-only-delivery" aria-label="Permalink to &quot;D3 — WebP-only delivery&quot;">​</a></h3><p>Re-encode image masters → <strong>WebP</strong> (universal support ~97%+, ~30% smaller than JPEG, works with existing bare <code>&lt;img src&gt;</code> — no <code>&lt;picture&gt;</code> markup churn). <strong>No JPEG fallback and no AVIF</strong> for v1: the ~3% ancient-device gap is accepted (decided 2026-07-07). Because masters are retained (D2), JPEG fallback or AVIF can be re-encoded at any time with zero lock-in — deferred, not foreclosed.</p><h3 id="d4-—-local-encode-committed-derivatives-ci-never-encodes" tabindex="-1">D4 — Local encode, committed derivatives; CI never encodes <a class="header-anchor" href="#d4-—-local-encode-committed-derivatives-ci-never-encodes" aria-label="Permalink to &quot;D4 — Local encode, committed derivatives; CI never encodes&quot;">​</a></h3><p>Image re-encode runs <strong>locally and deliberately</strong> (extending the existing curated image pipeline — <code>fetch-assets.ts</code> et al.), and the WebP derivatives are <strong>committed</strong> (GH Pages serves from git). CI remains a <strong>validator + deployer</strong>, never an encoder. <strong>Masters stay out of main git</strong> (git-LFS preferred; external bucket an option — settled at Slice C). Rationale: matches the existing local-curated + per-image-review model, keeps deploys fast/deterministic, avoids re-encoding 5,300 images on every push, and avoids putting masters on the CI bandwidth path.</p><h2 id="slices-tracked-under-373" tabindex="-1">Slices (tracked under #373) <a class="header-anchor" href="#slices-tracked-under-373" aria-label="Permalink to &quot;Slices (tracked under #373)&quot;">​</a></h2><ul><li><strong>A — i18n source relocation</strong> (D2 i18n). Cheapest, highest #373 impact. Move tree, repoint bundler, fix raw-path tests.</li><li><strong>B — <code>assetUrl()</code> spine</strong> (D1). The refactor; canonicalizes audio base. <strong>Closes mobile #191.</strong></li><li><strong>C — WebP masters/derivatives</strong> (D2 images + D3 + D4). Largest: masters store + git-LFS decision + local encode pipeline over ~5,300 images.</li></ul><p>Order A → B → C. A and B are tractable immediately; C is a larger, separable effort.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive</strong></p><ul><li>#373 root cause fixed on two axes: file count (A) and bytes (C); deploys stop being a coin-flip.</li><li>Mobile streaming (#191) falls out of B for free — one spine serves mobile-now and optional-CDN-prod-later.</li><li>Audio-<code>base</code> double-prepend bug eliminated.</li><li>Git image weight drops (WebP replaces JPEG; masters leave main history).</li></ul><p><strong>Negative / risks</strong></p><ul><li><strong>Broad refactor surface</strong> (B touches ~9 resolvers): a missed chokepoint = silent 404 in the mobile/CDN build. Mitigation: a mobile-build 404 sweep over every route before shipping.</li><li><strong>~3% ancient devices lose images</strong> under WebP-only (D3, accepted).</li><li><strong>Masters storage</strong> adds a git-LFS/external dependency and process discipline (re-encode before commit).</li><li><strong>Test churn:</strong> tests that read <code>static/data/i18n/&lt;locale&gt;/…</code> raw paths must repoint to <code>i18n-src/</code> (A).</li></ul><p><strong>Rollback</strong>: A is a directory move + a bundler path change (revert = move back). B is env-gated and additive (the helper defaults to today&#39;s <code>base</code>; browser build unchanged). C is regenerable from masters and reversible to JPEG. No irreversible step.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>#373 (deploy flakiness) · #191 (mobile gallery/audio streaming) · #376 (future KTX2 textures)</li><li><a href="./ADR-078">ADR-078</a> (mobile stream-heavy bundle — origin consumer of D1)</li><li>ADR-057 (locale cookie) · <code>scripts/build-i18n-bundles.mjs</code> · <code>src/lib/image-hero.ts</code> · <code>src/lib/image-vision.ts</code> · <code>src/lib/data.ts</code></li></ul><hr><p><em>Orrery · ADR-079 · Asset-origin spine + source/derived separation + WebP · July 2026</em></p>',33)])])}const h=o(r,[["render",a]]);export{g as __pageData,h as default};
